import { test, expect } from '@playwright/test';

test.describe('Session Expiration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    // Simulate user login or token generation here
  });

  test('should display session expired message after token timeout', async ({ page }) => {
    // Simulate waiting for the token to expire
    await page.waitForTimeout(60000); // Adjust timeout as necessary

    // Check for session expired message
    const message = await page.getByText('Your session has expired. Please log in again.');
    await expect(message).toBeVisible();
  });

  test('should redirect to login page after session expiration', async ({ page }) => {
    // Simulate waiting for the token to expire
    await page.waitForTimeout(60000); // Adjust timeout as necessary

    // Check if redirected to login page
    await expect(page).toHaveURL('https://example.com/login'); // Replace with the actual login URL
  });
});
